SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,     im.STATUS                                             AS item_status,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'     END                                                   AS item_loc_status_desc,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'     END                                                   AS order_control_desc,     ril.PRIMARY_REPL_SUPPLIER                             AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     ril.MIN_STOCK                                         AS min_stock,     ril.MAX_STOCK                                         AS max_stock,     ril.SOURCE_WH                                         AS source_warehouse,      ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost,     il.SELLING_UNIT_RETAIL                                AS unit_retail,     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)                                                           AS soh_cost_value,     CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) = 0  THEN 'OUT OF STOCK'         WHEN NVL(ils.STOCK_ON_HAND, 0) < NVL(ril.MIN_STOCK, 0) THEN 'BELOW MIN'         WHEN NVL(ils.STOCK_ON_HAND, 0) > NVL(ril.MAX_STOCK, 0) THEN 'ABOVE MAX'         ELSE 'WITHIN RANGE'     END                                                   AS stock_position,      last_rcpt.LAST_RECEIVE_DATE                           AS last_receive_date,     last_rcpt.LAST_RECEIVE_QTY                            AS last_receive_qty,     CASE         WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN NULL         ELSE TRUNC(SYSDATE) - TRUNC(last_rcpt.LAST_RECEIVE_DATE)     END                                                   AS days_since_last_receipt,      last_roq.LAST_ROQ_DATE                                AS last_roq_date,     last_roq.LAST_ROQ_QTY                                 AS last_roq_qty,     CASE         WHEN last_roq.LAST_ROQ_DATE IS NULL THEN NULL         ELSE TRUNC(SYSDATE) - TRUNC(last_roq.LAST_ROQ_DATE)     END                                                   AS days_since_last_roq,      NVL(open_po.OPEN_PO_COUNT, 0)                         AS open_po_count,     NVL(open_po.OPEN_PO_QTY, 0)                           AS open_po_qty,     open_po.OLDEST_PO_DATE                                AS oldest_open_po_date,     open_po.NEWEST_PO_DATE                                AS newest_open_po_date,     NVL(open_tsf.OPEN_TSF_COUNT, 0)                       AS open_tsf_count,     NVL(open_tsf.OPEN_TSF_QTY, 0)                         AS open_tsf_qty,     open_tsf.OLDEST_TSF_DATE                              AS oldest_open_tsf_date,     NVL(open_po.OPEN_PO_QTY, 0)         + NVL(open_tsf.OPEN_TSF_QTY, 0)                  AS total_open_supply_qty,      CASE WHEN smf.ITEM IS NOT NULL THEN 'Y' ELSE 'N' END  AS supplier_min_fail_ind,     smf.ERROR_MSG                                         AS supplier_min_fail_msg,      isc.LEAD_TIME                                         AS lead_time,     isc.PICKUP_LEAD_TIME                                  AS pickup_lead_time,     isc.UNIT_COST                                         AS unit_cost,     isc.SUPP_PACK_SIZE                                    AS supp_pack_size,      CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL          THEN 'Y' ELSE 'N' END                            AS ex_never_received,     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0               AND NVL(open_po.OPEN_PO_QTY, 0) = 0               AND NVL(open_tsf.OPEN_TSF_QTY, 0) = 0          THEN 'Y' ELSE 'N' END                            AS ex_oos_no_supply,     CASE WHEN smf.ITEM IS NOT NULL          THEN 'Y' ELSE 'N' END                            AS ex_supplier_min_fail,     CASE WHEN last_roq.LAST_ROQ_DATE IS NULL               OR TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE) - 7          THEN 'Y' ELSE 'N' END                            AS ex_no_roq_7_days,     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) < NVL(ril.MIN_STOCK, 0)               AND NVL(open_po.OPEN_PO_QTY, 0) = 0               AND NVL(open_tsf.OPEN_TSF_QTY, 0) = 0          THEN 'Y' ELSE 'N' END                            AS ex_below_min_no_supply,     CASE WHEN NVL(sp.SUP_STATUS, 'X') != 'A'               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'Y' ELSE 'N' END                            AS ex_inactive_supplier,     CASE WHEN NVL(isc.PICKUP_LEAD_TIME, 0) = 0               AND ril.STOCK_CAT IN ('C','D','L','W')          THEN 'Y' ELSE 'N' END                            AS ex_missing_pickup_lt,     CASE WHEN NVL(isc.UNIT_COST, 0) = 0          THEN 'Y' ELSE 'N' END                            AS ex_missing_unit_cost,      (CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN smf.ITEM IS NOT NULL THEN 1 ELSE 0 END      + CASE WHEN last_roq.LAST_ROQ_DATE IS NULL                  OR TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE)-7              THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN NVL(sp.SUP_STATUS,'X')!='A'                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.UNIT_COST,0)=0 THEN 1 ELSE 0 END     )                                                     AS total_exception_count,      CASE         WHEN NVL(ils.STOCK_ON_HAND,0)=0              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0         THEN 'CRITICAL - OOS with No Supply'         WHEN smf.ITEM IS NOT NULL         THEN 'HIGH - Supplier Minimum Failure'         WHEN NVL(sp.SUP_STATUS,'X')!='A'              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'HIGH - Inactive Supplier on Repl'         WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL         THEN 'HIGH - Never Received'         WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0         THEN 'HIGH - Below Min, No Open Supply'         WHEN last_roq.LAST_ROQ_DATE IS NULL              OR TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE)-7         THEN 'MEDIUM - No ROQ in 7 Days'         WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'MEDIUM - Missing Pickup Lead Time'         WHEN NVL(isc.UNIT_COST,0)=0         THEN 'MEDIUM - Missing Unit Cost'         ELSE 'LOW - Monitor'     END                                                   AS exception_priority,      CASE         WHEN NVL(ils.STOCK_ON_HAND,0)=0              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0         THEN 'Raise emergency PO or transfer immediately; review rplext batch log'         WHEN smf.ITEM IS NOT NULL         THEN 'Review supplier minimum setup on SUP_INV_MGMT; adjust order qty or min'         WHEN NVL(sp.SUP_STATUS,'X')!='A'         THEN 'Reactivate supplier or assign alternate supplier on REPL_ITEM_LOC'         WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL         THEN 'Verify item is ordered and supplier relationship is active; check SHIPMENT table'         WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)              AND NVL(open_po.OPEN_PO_QTY,0)=0         THEN 'Repl below min with no open order - check rplext.ksh batch and order control'         WHEN last_roq.LAST_ROQ_DATE IS NULL         THEN 'No ROQ ever generated - verify replenishment batch ran and REPL_DAY configured'         WHEN TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE)-7         THEN 'ROQ not generated in 7 days - check REPL_DAY schedule and rplext batch logs'         WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0         THEN 'Set PICKUP_LEAD_TIME on ITEM_SUPP_COUNTRY for this supplier'         WHEN NVL(isc.UNIT_COST,0)=0         THEN 'Set UNIT_COST on ITEM_SUPP_COUNTRY - cost required for PO generation'         ELSE 'Review batch logs and replenishment configuration'     END                                                   AS recommended_action,      ril.LAST_UPDATE_DATETIME                              AS last_repl_attr_update  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM         = il.ITEM                                                      AND  ril.LOCATION     = il.LOC                                                      AND  ril.LOC_TYPE     = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM         = im.ITEM                                                      AND  im.TRAN_LEVEL    = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT          = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT          = c.DEPT                                                      AND  im.CLASS         = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT          = sc.DEPT                                                      AND  im.CLASS         = sc.CLASS                                                      AND  im.SUBCLASS      = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION     = st.STORE                                                      AND  il.LOC_TYPE      = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION     = wh.WH                                                      AND  il.LOC_TYPE      = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM         = ils.ITEM                                                      AND  ril.LOCATION     = ils.LOC                                                      AND  ils.LOC_TYPE     = ril.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM         = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN (         SELECT             ss.ITEM,             sh.TO_LOC                                     AS loc,             MAX(sh.RECEIVE_DATE)                          AS last_receive_date,             SUM(ss.QTY_RECEIVED)                          AS last_receive_qty         FROM  MFCS_RDS.RDS_WV_SHIPSKU              ss         JOIN  MFCS_RDS.RDS_WV_SHIPMENT             sh  ON  ss.SHIPMENT = sh.SHIPMENT         GROUP BY ss.ITEM, sh.TO_LOC     ) last_rcpt                                           ON  ril.ITEM     = last_rcpt.ITEM                                                          AND  ril.LOCATION = last_rcpt.loc      LEFT JOIN (         SELECT             rr.ITEM,             rr.LOCATION,             rr.LOC_TYPE,             MAX(rr.REPL_DATE)                             AS last_roq_date,             MAX(rr.ORDER_ROQ)                 KEEP (DENSE_RANK LAST ORDER BY rr.REPL_DATE)                                                           AS last_roq_qty         FROM  MFCS_RDS.RDS_WV_REPL_RESULTS         rr         GROUP BY rr.ITEM, rr.LOCATION, rr.LOC_TYPE     ) last_roq                                            ON  ril.ITEM     = last_roq.ITEM                                                          AND  ril.LOCATION = last_roq.LOCATION                                                          AND  ril.LOC_TYPE = last_roq.LOC_TYPE      LEFT JOIN (         SELECT             ol.ITEM,             ol.LOCATION,             COUNT(DISTINCT oh.ORDER_NO)                   AS open_po_count,             SUM(ol.QTY_ORDERED - NVL(ol.QTY_RECEIVED, 0)) AS open_po_qty,             MIN(oh.WRITTEN_DATE)                          AS oldest_po_date,             MAX(oh.WRITTEN_DATE)                          AS newest_po_date         FROM  MFCS_RDS.RDS_WV_ORDLOC               ol         JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh  ON  ol.ORDER_NO = oh.ORDER_NO         WHERE oh.STATUS IN ('W','S','A')         GROUP BY ol.ITEM, ol.LOCATION     ) open_po                                             ON  ril.ITEM     = open_po.ITEM                                                          AND  ril.LOCATION = open_po.LOCATION      LEFT JOIN (         SELECT             td.ITEM,             th.TO_LOC                                     AS loc,             COUNT(DISTINCT th.TSF_NO)                     AS open_tsf_count,             SUM(td.TSF_QTY - NVL(td.RECEIVED_QTY, 0))    AS open_tsf_qty,             MIN(th.CREATE_DATE)                           AS oldest_tsf_date         FROM  MFCS_RDS.RDS_WV_TSFDETAIL            td         JOIN  MFCS_RDS.RDS_WV_TSFHEAD              th  ON  td.TSF_NO = th.TSF_NO         WHERE th.STATUS IN ('A','S','IR')         GROUP BY td.ITEM, th.TO_LOC     ) open_tsf                                            ON  ril.ITEM     = open_tsf.ITEM                                                          AND  ril.LOCATION = open_tsf.loc      LEFT JOIN MFCS_RDS.RDS_WV_SUPS_MIN_FAIL       smf  ON  ril.ITEM       = smf.ITEM                                                         AND  ril.PRIMARY_REPL_SUPPLIER = smf.SUPPLIER  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'     AND (         last_rcpt.LAST_RECEIVE_DATE IS NULL         OR (NVL(ils.STOCK_ON_HAND,0)=0             AND NVL(open_po.OPEN_PO_QTY,0)=0             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)         OR smf.ITEM IS NOT NULL         OR last_roq.LAST_ROQ_DATE IS NULL         OR TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE)-7         OR (NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)             AND NVL(open_po.OPEN_PO_QTY,0)=0             AND NVL(open_tsf.OPEN_TSF_QTY,0)=0)         OR NVL(sp.SUP_STATUS,'X') != 'A'         OR (NVL(isc.PICKUP_LEAD_TIME,0)=0             AND ril.STOCK_CAT IN ('C','D','L','W'))         OR NVL(isc.UNIT_COST,0)=0     )  ORDER BY     (CASE WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0)=0                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN smf.ITEM IS NOT NULL THEN 1 ELSE 0 END      + CASE WHEN last_roq.LAST_ROQ_DATE IS NULL                  OR TRUNC(last_roq.LAST_ROQ_DATE) < TRUNC(SYSDATE)-7 THEN 1 ELSE 0 END      + CASE WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)                  AND NVL(open_po.OPEN_PO_QTY,0)=0                  AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 1 ELSE 0 END      + CASE WHEN NVL(sp.SUP_STATUS,'X')!='A'                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.PICKUP_LEAD_TIME,0)=0                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(isc.UNIT_COST,0)=0 THEN 1 ELSE 0 END     ) DESC,     CASE         WHEN NVL(ils.STOCK_ON_HAND,0)=0              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0         THEN 'CRITICAL - OOS with No Supply'         WHEN smf.ITEM IS NOT NULL THEN 'HIGH - Supplier Minimum Failure'         WHEN NVL(sp.SUP_STATUS,'X')!='A'              AND ril.STOCK_CAT IN ('C','D','L','W') THEN 'HIGH - Inactive Supplier on Repl'         WHEN last_rcpt.LAST_RECEIVE_DATE IS NULL THEN 'HIGH - Never Received'         WHEN NVL(ils.STOCK_ON_HAND,0) < NVL(ril.MIN_STOCK,0)              AND NVL(open_po.OPEN_PO_QTY,0)=0              AND NVL(open_tsf.OPEN_TSF_QTY,0)=0 THEN 'HIGH - Below Min, No Open Supply'         ELSE 'MEDIUM'     END,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END